def inp(mid,name,v,unit,sid,loc):return dict(metric_id=mid,name=name,value=v,unit=unit,source=sid,location=loc)
def op(mid,name,exp,expected,unit,meaning):return dict(metric_id=mid,name=name,expression=exp,expected=expected,unit=unit,meaning=meaning,tolerance=0.00001)
def case(id,title,period,scope,inputs,outputs,boundary):cases.append(dict(id=id,title=title,period=period,scope=scope,inputs=inputs,outputs=outputs,boundary=boundary))
